ALTER TABLE public.notifications ADD COLUMN communication jsonb;
COMMENT ON COLUMN public.notifications.communication IS 'Preparation-only transactional communication evidence, not an email queue. Legacy inbox and managed sent-email history remain separate; no delivery worker consumes this field.';
CREATE UNIQUE INDEX notification_communication_dedupe ON public.notifications ((communication->>'dedupeKey')) WHERE communication IS NOT NULL;
CREATE FUNCTION public.communication_notice_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' AND OLD.communication IS NOT NULL THEN RAISE EXCEPTION 'Communication history must be retained'; END IF;
 IF TG_OP='UPDATE' AND OLD.communication IS NOT NULL AND (NEW.communication IS DISTINCT FROM OLD.communication OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.title IS DISTINCT FROM OLD.title OR NEW.body IS DISTINCT FROM OLD.body OR NEW.ride_request_id IS DISTINCT FROM OLD.ride_request_id OR NEW.link IS DISTINCT FROM OLD.link) THEN RAISE EXCEPTION 'Communication evidence is immutable; append a version'; END IF;
 IF TG_OP='INSERT' AND NEW.communication IS NOT NULL AND (current_user NOT IN ('postgres','service_role','supabase_admin') OR NEW.communication->>'state' NOT IN ('prepared','suppressed','not_configured','canceled') OR NEW.communication->>'channel' NOT IN ('in_app','email') OR NEW.communication->>'dedupeKey' IS NULL) THEN RAISE EXCEPTION 'Communication preparation is server-managed'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER communication_notice_evidence_guard BEFORE INSERT OR UPDATE OR DELETE ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.communication_notice_guard();
CREATE FUNCTION public.list_communication_preparations(_admin boolean DEFAULT false) RETURNS SETOF public.notifications LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT n.* FROM public.notifications n WHERE n.communication IS NOT NULL AND EXISTS(SELECT 1 FROM public.user_profiles p WHERE p.user_id=auth.uid() AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL) AND ((NOT _admin AND n.user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.workspace_id=(n.communication->>'workspaceId')::uuid AND m.user_id=auth.uid() AND m.removed_at IS NULL AND w.status='active' AND NOT w.is_test_account)) OR (_admin AND public.admin_can('messaging','read') AND public.admin_can_account((n.communication->>'workspaceId')::uuid))) ORDER BY n.created_at DESC LIMIT 200 $$;
REVOKE ALL ON FUNCTION public.list_communication_preparations(boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.list_communication_preparations(boolean) TO authenticated;
ALTER TABLE public.provider_network_profiles ADD COLUMN customer_communication_settings jsonb;
ALTER TABLE public.trips ADD COLUMN customer_driver_withheld boolean, ADD COLUMN communication_timezone text;
COMMENT ON COLUMN public.trips.communication_timezone IS 'Explicit authoritative IANA timezone for reminder preparation; NULL never defaults to Eastern. No existing rows backfilled.';
CREATE FUNCTION public.customer_sharing_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME='provider_network_profiles' AND (TG_OP='INSERT' AND NEW.customer_communication_settings IS NOT NULL OR TG_OP='UPDATE' AND NEW.customer_communication_settings IS DISTINCT FROM OLD.customer_communication_settings) AND current_setting('app.customer_sharing_confirmed',true) IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Explicit sharing confirmation required'; END IF; IF TG_TABLE_NAME='trips' AND TG_OP='UPDATE' AND (NEW.customer_driver_withheld IS DISTINCT FROM OLD.customer_driver_withheld OR NEW.communication_timezone IS DISTINCT FROM OLD.communication_timezone) AND current_setting('app.customer_sharing_confirmed',true) IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Authorized operations confirmation required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER customer_sharing_profile_guard BEFORE INSERT OR UPDATE ON public.provider_network_profiles FOR EACH ROW EXECUTE FUNCTION public.customer_sharing_guard();
CREATE TRIGGER customer_sharing_trip_guard BEFORE UPDATE ON public.trips FOR EACH ROW EXECUTE FUNCTION public.customer_sharing_guard();
CREATE FUNCTION public.save_customer_communication_settings(_ws uuid,_settings jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.can_manage_provider_customer_pricing(_ws) OR jsonb_typeof(_settings)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(_settings) k WHERE k NOT IN ('businessName','dispatchPhone','email','shareDriverName','shareDriverPhone')) OR length(coalesce(_settings->>'businessName',''))>160 OR length(coalesce(_settings->>'dispatchPhone',''))>32 OR length(coalesce(_settings->>'email',''))>254 OR jsonb_typeof(_settings->'shareDriverName')<>'boolean' OR jsonb_typeof(_settings->'shareDriverPhone')<>'boolean' THEN RAISE EXCEPTION 'Settings unavailable'; END IF;
 PERFORM set_config('app.customer_sharing_confirmed','true',true);PERFORM set_config('app.dispatch_contact_confirmed','true',true);
 UPDATE public.provider_network_profiles SET customer_communication_settings=_settings,trip_dispatch_phone=nullif(trim(_settings->>'dispatchPhone'),''),trip_dispatch_phone_designated=nullif(trim(_settings->>'dispatchPhone'),'') IS NOT NULL WHERE workspace_id=_ws;
 IF NOT FOUND THEN RAISE EXCEPTION 'Business identity required'; END IF;
 INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) SELECT _ws,'customer_communication_settings_confirmed',auth.uid(),p.mfn_id,w.mfn_id,jsonb_build_object('shareDriverName',_settings->'shareDriverName','shareDriverPhone',_settings->'shareDriverPhone') FROM public.user_profiles p,public.workspaces w WHERE p.user_id=auth.uid() AND w.id=_ws; END $$;
REVOKE ALL ON FUNCTION public.save_customer_communication_settings(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_customer_communication_settings(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.set_trip_communication_override(_trip uuid,_withhold boolean,_timezone text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ws uuid; BEGIN
 SELECT coalesce(t.workspace_id,d.workspace_id,t.network_provider_workspace_id) INTO ws FROM public.trips t LEFT JOIN public.drivers d ON d.id=t.driver_id WHERE t.id=_trip FOR UPDATE OF t;
 IF ws IS NULL OR NOT public.can_manage_provider_customer_pricing(ws) OR _withhold IS NULL OR (_timezone IS NOT NULL AND NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=_timezone AND name LIKE '%/%')) THEN RAISE EXCEPTION 'Trip unavailable'; END IF;
 PERFORM set_config('app.customer_sharing_confirmed','true',true); UPDATE public.trips SET customer_driver_withheld=_withhold,communication_timezone=_timezone WHERE id=_trip;
 INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) SELECT ws,'trip_communication_override',auth.uid(),p.mfn_id,w.mfn_id,jsonb_build_object('tripId',_trip,'withheld',_withhold,'timezone',_timezone) FROM public.user_profiles p,public.workspaces w WHERE p.user_id=auth.uid() AND w.id=ws; END $$;
REVOKE ALL ON FUNCTION public.set_trip_communication_override(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_trip_communication_override(uuid,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.patient_trip_contacts(_request uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.trips;ws uuid;d public.drivers;p public.provider_network_profiles;confirmed boolean;sharing jsonb; BEGIN IF NOT public.patient_request_access(_request) THEN RETURN NULL; END IF; SELECT * INTO t FROM public.trips WHERE ride_request_id=_request ORDER BY created_at DESC LIMIT 1; SELECT * INTO d FROM public.drivers WHERE id=t.driver_id;ws:=coalesce(t.workspace_id,d.workspace_id,t.network_provider_workspace_id); IF ws IS NULL THEN SELECT r.workspace_id INTO ws FROM public.ride_requests r JOIN public.workspaces w ON w.id=r.workspace_id WHERE r.id=_request AND w.account_type='provider'; END IF;SELECT * INTO p FROM public.provider_network_profiles WHERE workspace_id=ws;sharing:=p.customer_communication_settings;confirmed:=t.status IN ('confirmed','approved','assigned','in_progress','completed','scheduled','accepted'); RETURN jsonb_build_object('dispatchPhone',CASE WHEN confirmed AND p.trip_dispatch_phone_designated THEN p.trip_dispatch_phone END,'businessName',CASE WHEN confirmed THEN sharing->>'businessName' END,'email',CASE WHEN confirmed THEN sharing->>'email' END,'driverName',CASE WHEN t.driver_id IS NOT NULL AND t.status IN ('assigned','in_progress','completed') AND sharing->>'shareDriverName'='true' AND NOT coalesce(t.customer_driver_withheld,false) THEN trim(d.first_name||' '||d.last_name) END,'driverPhone',CASE WHEN t.driver_id IS NOT NULL AND t.status IN ('assigned','in_progress','completed') AND t.patient_contact_driver_id=t.driver_id AND t.patient_driver_provider_confirmed AND t.patient_driver_confirmed AND (sharing IS NULL OR sharing->>'shareDriverPhone'='true') AND NOT coalesce(t.customer_driver_withheld,false) THEN t.patient_driver_phone END); END $$;
ALTER TABLE public.trip_invoice_access_tokens ADD COLUMN customer_workspace_id uuid, ADD COLUMN provider_workspace_id uuid, ADD COLUMN invoice_version uuid, ADD COLUMN environment text, ADD COLUMN first_view_at timestamptz;
COMMENT ON COLUMN public.trip_invoice_access_tokens.customer_workspace_id IS 'Exact authorized bill-to/patient binding; legacy NULL token bindings fail closed. No token contents stored.';
